/** Persistent semantic cache for the authoritative context store. It is an index, never a source of truth. */
import {createRequire} from 'node:module';import {createHash} from 'node:crypto';
const require=createRequire(import.meta.url);const fail=message=>Object.assign(new Error(message),{code:'VECTOR_UNAVAILABLE'});const APPLICATION_ID=0x414f4356,SCHEMA_VERSION=1;
function safePath(value){if(typeof value!=='string'||!value.trim()||value.includes('\0')||/^(?:https?:|file:|\\\\|\/\/)/i.test(value)||(value.startsWith(':')&&value!==':memory:'))throw fail('vector index path is invalid');return value;}
function vector(value){if(!Array.isArray(value)||!value.length||value.length>4096||value.some(x=>typeof x!=='number'||!Number.isFinite(x)))throw fail('embedding is invalid');return value;}
const encode=value=>Buffer.from(new Float64Array(value).buffer);
const decode=value=>{const b=Buffer.isBuffer(value)?value:Buffer.from(value);return [...new Float64Array(b.buffer,b.byteOffset,b.byteLength/8)];};
function cosine(a,b){if(a.length!==b.length)return -1;let dot=0,aa=0,bb=0;for(let i=0;i<a.length;i++){dot+=a[i]*b[i];aa+=a[i]*a[i];bb+=b[i]*b[i];}return aa&&bb?dot/Math.sqrt(aa*bb):-1;}
export function createContextVectorIndex({dbPath,provider,maxRows=Number.POSITIVE_INFINITY}){
 if(!provider||typeof provider.embedQuery!=='function')throw fail('embedding provider is unavailable');const {DatabaseSync}=require('node:sqlite');const db=new DatabaseSync(safePath(dbPath),{enableForeignKeyConstraints:true,enableDoubleQuotedStringLiterals:false});
 db.exec('PRAGMA busy_timeout=3000');
 const app=db.prepare('PRAGMA application_id').get().application_id,version=db.prepare('PRAGMA user_version').get().user_version;
 if(app===0&&version===0){const count=db.prepare("SELECT count(*) AS n FROM sqlite_master WHERE name NOT LIKE 'sqlite_%'").get().n;if(count!==0){db.close();throw fail('vector database is not owned by agentOS context')}db.exec('BEGIN; CREATE TABLE context_vectors(scope_id TEXT NOT NULL,memory_id TEXT NOT NULL,revision INTEGER NOT NULL,model TEXT NOT NULL,dimensions INTEGER NOT NULL,content_hash TEXT NOT NULL,embedding BLOB NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(scope_id,memory_id,revision)) STRICT; CREATE INDEX context_vectors_scope ON context_vectors(scope_id,memory_id,revision); PRAGMA application_id='+APPLICATION_ID+'; PRAGMA user_version='+SCHEMA_VERSION+'; COMMIT;');}
 else if(app!==APPLICATION_ID||version!==SCHEMA_VERSION){db.close();throw fail('vector database version is not supported')}
 let closed=false,tail=Promise.resolve();const model=()=>typeof provider.getModelName==='function'?String(provider.getModelName()):'unknown';
 const task=fn=>{const run=tail.then(()=>closed?undefined:fn());tail=run.catch(()=>{});return run;};
 return {
  enqueue(memory){if(closed)return;const snapshot=structuredClone(memory);void task(async()=>{const modelName=model();const v=vector(await provider.embedQuery(snapshot.content.slice(0,2000)));try{db.exec('BEGIN IMMEDIATE');db.prepare('INSERT INTO context_vectors(scope_id,memory_id,revision,model,dimensions,content_hash,embedding,updated_at) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(scope_id,memory_id,revision) DO UPDATE SET model=excluded.model,dimensions=excluded.dimensions,content_hash=excluded.content_hash,embedding=excluded.embedding,updated_at=excluded.updated_at').run(snapshot.scopeId,snapshot.id,snapshot.revision,modelName,v.length,createHash('sha256').update(snapshot.content).digest('hex'),encode(v),Date.now());db.prepare('DELETE FROM context_vectors WHERE scope_id=? AND memory_id=? AND revision<>?').run(snapshot.scopeId,snapshot.id,snapshot.revision);db.exec('COMMIT');}catch(error){try{db.exec('ROLLBACK');}catch{}throw error;}});},
  remove(scopeId,memoryId){if(closed)return;void task(()=>db.prepare('DELETE FROM context_vectors WHERE scope_id=? AND memory_id=?').run(scopeId,memoryId));},
  async search({scopeId,query,candidates,limit=8,minScore=-1}){if(closed)return[];try{await tail;const modelName=model();const q=vector(await provider.embedQuery(String(query).slice(0,2000)));const allowed=Array.isArray(candidates)?new Map(candidates.map(x=>[x.id,x.revision])):null;if(allowed&&allowed.size===0)return[];const wanted=Math.max(1,Math.min(500,limit)),floor=Math.max(-1,Math.min(1,minScore));let sql='SELECT memory_id,revision,embedding FROM context_vectors WHERE scope_id=? AND model=? AND dimensions=? ORDER BY memory_id,revision DESC',params=[scopeId,modelName,q.length];if(Number.isSafeInteger(maxRows)&&maxRows>0){sql+=' LIMIT ?';params.push(maxRows);}const statement=db.prepare(sql),rows=typeof statement.iterate==='function'?statement.iterate(...params):statement.all(...params),seen=new Set(),best=[];for(const row of rows){if(seen.has(row.memory_id))continue;seen.add(row.memory_id);if(allowed&&allowed.get(row.memory_id)!==row.revision)continue;const score=cosine(q,decode(row.embedding));if(!Number.isFinite(score)||score<floor||score>1)continue;const hit={id:row.memory_id,revision:row.revision,score};if(best.length<wanted){best.push(hit);continue;}let worst=0;for(let i=1;i<best.length;i++)if(best[i].score<best[worst].score)worst=i;if(score>best[worst].score)best[worst]=hit;}return best.sort((a,b)=>b.score-a.score);}catch{return[];}},
  async close(){if(closed)return;await tail;closed=true;db.close();}
 };
}
