const messages={INVALID_INPUT:'请求字段不正确，请检查输入。',NOT_FOUND:'没有可访问的记录。',VERSION_CONFLICT:'内容已被更新，请刷新后重试。',IDEMPOTENCY_CONFLICT:'操作编号已用于其他内容。',ENTITY_CONFLICT:'对象名称或别名已存在。',TYPE_MISMATCH:'不同类型的对象不能合并。',MERGE_CONFLICT:'合并会破坏已有关系。',INVALID_RELATION:'关系不符合类型定义。',INVALID_EVIDENCE:'原文片段与来源不一致。',EVIDENCE_REQUIRED:'确认前必须提供来源和原文。',INVALID_REFERENCE:'引用记录当前不可用。',INVALID_TRANSITION:'状态不能这样变更。',SECRET_REJECTED:'内容疑似包含凭据，已拒绝保存。',DOCUMENT_FORMAT_UNSUPPORTED:'暂不支持这种文档格式，请转换为 DOCX、XLSX、PPTX、PDF、ODF 或 RTF。',DOCUMENT_PARSE_FAILED:'文档无法解析，可能已损坏、加密或没有可提取文字。',DOCUMENT_PARSER_UNAVAILABLE:'未安装 officeparser，二进制文档（DOCX/XLSX/PPTX/PDF 等）解析暂不可用；纯文本（≤ 4 MB）仍可上传。安装后在 DSH 中重试：pnpm add officeparser',LIMIT_EXCEEDED:'处理范围过大，请缩小范围。',STORE_CLOSED:'记忆服务已停止。',STORE_FULL:'本地磁盘空间不足，请清理空间后重试。',STORE_UNAVAILABLE:'记忆或知识库存储暂不可用。',STORE_FAILURE:'记忆或知识库操作未完成。',ABORTED:'操作已取消或解析超时。'};
export function safeContextError(error){const code=Object.hasOwn(messages,error?.code)?error.code:'INTERNAL';return{code,message:messages[code]??'操作未完成。',details:{...(typeof error?.field==='string'?{field:error.field}:{})}};}
function object(value,keys){if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!keys.includes(k)||['__proto__','constructor','prototype'].includes(k)))throw Object.assign(new Error('invalid'),{code:'INVALID_INPUT'});return value;}
const keys={bootstrap:['sessionId'],scopes:[],memories:['scopeId','query','lifecycle','epistemic','layer','limit','knownAt','validAt'],memory:['scopeId','id','knownAt','validAt'],versions:['scopeId','id'],entities:['scopeId','query','limit'],graph:['scopeId','rootId','depth','includePending','limit','knownAt','validAt'],reviews:['scopeId'],schema:[],usage:['scopeId','sessionId','limit'],changes:['scopeId','limit'],documents:['scopeId','limit'],'documents/search':['scopeId','query','limit','threshold','searchMode','documentIds','metadata'],'document/chunks':['scopeId','id','limit'],'document/upload':['scopeId','filename','mimeType','content','dataBase64','metadata'],'document/reindex':['scopeId','id'],'document/delete':['scopeId','id'],'documents/delete':['scopeId','ids'],'memory/save':['scopeId','content','kind','layer','importance','expiresAt','metadata','idempotencyKey','validFrom','validTo','entityIds'],'memory/revise':['scopeId','id','expectedRevision','content','kind','layer','importance','expiresAt','reason','validFrom','validTo'],'memory/transition':['scopeId','id','expectedRevision','layer','importance','expiresAt','reason'],'memory/retire':['scopeId','id','expectedRevision','reason'],'entity/create':['scopeId','name','type','aliases'],'entity/merge':['scopeId','keepId','mergeId','keepRevision','mergeRevision','reason'],'relation/create':['scopeId','subjectId','predicate','objectId','sourceId','sourceMemoryId','quote','validFrom','validTo'],'relation/review':['scopeId','id','expectedRevision','decision','reason'],'schema/check':['scopeId','subjectId','predicate','objectId','sourceId','quote','validFrom','validTo'],'usage/policy':['sessionId','scopeId','memoryId','mode','paused','expectedRevision'],'verify-key':['apiKey'],models:[]};
export function createContextRpcHandler({service,credentials,config,distiller,fetcher=fetch}){return async function handle(endpoint,payload,signal){if(signal?.aborted)throw Object.assign(new Error('aborted'),{code:'ABORTED'});if(!Object.hasOwn(keys,endpoint))throw Object.assign(new Error('unknown'),{code:'NOT_FOUND'});const input=object(payload??{},keys[endpoint]);switch(endpoint){case'bootstrap':return service.bootstrap(input.sessionId);case'scopes':return{items:await service.listScopes()};case'memories':return{items:await service.listMemories(input)};case'memory':{const item=await service.getMemory(input);if(!item)throw Object.assign(new Error('missing'),{code:'NOT_FOUND'});return{item};}case'versions':return{items:await service.versions(input)};case'entities':return{items:service.listEntities(input)};case'graph':return await service.graph(input,{signal});case'reviews':return{items:service.listReviews(input)};case'schema':return service.schema();case'usage':return service.usage(input);case'changes':return{items:service.changes(input)};case'documents':return{items:await service.listDocuments(input,{signal})};case'documents/search':return{items:await service.searchDocuments(input,{signal})};case'document/chunks':return await service.listDocumentChunks(input,{signal});case'document/upload':return{item:await service.uploadDocument(input,{signal})};case'document/reindex':return await service.reindexDocument(input,{signal});case'document/delete':return await service.deleteDocument(input,{signal});case'documents/delete':return await service.deleteDocuments(input,{signal});case'memory/save':return{item:service.saveMemory(input,{actorRole:'human',kind:'manual'})};case'memory/revise':return{item:await service.reviseMemory(input,{actorRole:'human',signal})};case'memory/transition':return{item:await service.transitionMemory(input,{signal})};case'memory/retire':return{item:await service.retireMemory(input,{signal})};case'entity/create':return{item:service.createEntity(input)};case'entity/merge':return{item:service.mergeEntities(input)};case'relation/create':return{item:await service.createRelation(input,{signal})};case'relation/review':return{item:service.reviewRelation(input)};case'schema/check':return service.validateRelation(input);case'usage/policy':return{policy:await service.setUsagePolicy(input,{signal})};case'verify-key':return verifyDraftKey(input,config,fetcher,signal);case'models':return listConfiguredModels(credentials,config,distiller);default:throw Object.assign(new Error('unknown'),{code:'NOT_FOUND'});}}}
